#!/bin/bash

# --- Star Wars-style Crawl over Rick Astley ASCII Art ---
# Draws the static ANSI art image once, then scrolls chorus lines upward.
# Each line transitions through 5 font sizes (big at bottom -> tiny at top)
# and fades from bright Star Wars yellow (#FFE81F) through amber to dark.
# Only the character cells the text occupies are overwritten; the rest of
# the image shows through.

# --- Configuration ---
SCROLL_DELAY=0.10
LINE_STAGGER_FRAMES=12   # frames between successive line entries

# Chorus lines (long lines kept short enough to fit within image width)
CHORUS=(
    "Never gonna give you up"
    "Never gonna let you down"
    "Never gonna run around"
    "and desert you"
    "Never gonna make you cry"
    "Never gonna say goodbye"
)

# Font bands, top -> bottom on screen (smallest font first).
# Each band: name|font  (toilet-width is computed from terminal width)
BANDS=(
    "top|smbraille"     # band 0: tiny, very dim
    "upper|pagga"       # band 1: small
    "middle|smblock"    # band 2: medium
    "lower|letter"      # band 3: large ASCII
    "bottom|mono9"      # band 4: biggest, brightest
)
NUM_BANDS=${#BANDS[@]}

# Native image dimensions (the embedded ASCII art is exactly this size)
NATIVE_IMG_W=200
NATIVE_IMG_H=69

# --- Terminal size detection ---
TERM_ROWS=$(tput lines 2>/dev/null || echo 24)
TERM_COLS=$(tput cols 2>/dev/null || echo 80)
# Leave 1 row at the bottom so we don't trigger terminal scroll on the last newline.
CRAWL_ROWS=$(( TERM_ROWS - 1 ))
(( CRAWL_ROWS < 10 )) && CRAWL_ROWS=$TERM_ROWS
CRAWL_COLS=$TERM_COLS

# Toilet output width — give each font enough room to render the longest chorus line.
# Capping at CRAWL_COLS prevents overflow; larger values just get trimmed by toilet's wrap logic.
TOILET_WIDTH=$(( CRAWL_COLS > 60 ? CRAWL_COLS : 60 ))

# Color stops, top -> bottom (RGB triplets).  Used to interpolate per row.
COLOR_TOP_R=20    ; COLOR_TOP_G=10    ; COLOR_TOP_B=0       # near-black brown
COLOR_BOT_R=255   ; COLOR_BOT_G=232   ; COLOR_BOT_B=31      # Star Wars yellow #FFE81F

RESET=$'\e[0m'

if ! command -v toilet >/dev/null 2>&1; then
    echo "Error: 'toilet' command not found."
    exit 1
fi


# --- Embedded ASCII art (was ansii_rick.txt) ---
