# --- Load image with real ESC characters injected ---
mapfile -t IMAGE < <(get_art | sed $'s/\\[/\e[/g')
RAW_HEIGHT=${#IMAGE[@]}

# --- Pre-tokenize image into per-row cells (one cell per visible char) ---
DELIM=$'\x01'
declare -a ROW_CELLS_RAW
declare -a ROW_WIDTH

mapfile -t ROW_CELLS_RAW < <(
    printf '%s\n' "${IMAGE[@]}" | awk -v DELIM=$'\x01' -v RESET=$'\e[0m' '
    {
        out = ""
        n = length($0)
        i = 1
        pending = ""
        while (i <= n) {
            c = substr($0, i, 1)
            if (c == "\033") {
                seq = c
                i++
                if (i <= n && substr($0, i, 1) == "[") {
                    seq = seq "["
                    i++
                    while (i <= n) {
                        c2 = substr($0, i, 1)
                        seq = seq c2
                        i++
                        if (c2 ~ /[a-zA-Z]/) break
                    }
                }
                pending = pending seq
            } else {
                if (out == "") out = pending c RESET
                else out = out DELIM pending c RESET
                pending = ""
                i++
            }
        }
        print out
    }
    '
)

# Compute visible character width for each row
for (( r=0; r<RAW_HEIGHT; r++ )); do
    if [[ -z "${ROW_CELLS_RAW[$r]}" ]]; then
        ROW_WIDTH[r]=0
    else
        ROW_WIDTH[r]=$(awk -v s="${ROW_CELLS_RAW[$r]}" -v d=$'\x01' 'BEGIN{n=split(s,a,d); print n}')
    fi
done

RAW_WIDTH=${ROW_WIDTH[0]:-0}
for (( r=1; r<RAW_HEIGHT; r++ )); do
    (( ROW_WIDTH[r] > RAW_WIDTH )) && RAW_WIDTH=${ROW_WIDTH[r]}
done

