# (drop every STEP-th cell) such that RAW_WIDTH/STEP <= TERM_COLS and
# RAW_HEIGHT/STEP <= TERM_ROWS. Use the same step in both dimensions to
# preserve aspect ratio. STEP=1 means no scaling (image fits natively).
STEP_X=$(( (RAW_WIDTH + TERM_COLS - 1) / TERM_COLS ))
STEP_Y=$(( (RAW_HEIGHT + CRAWL_ROWS - 1) / CRAWL_ROWS ))
STEP=$STEP_X
(( STEP_Y > STEP )) && STEP=$STEP_Y
(( STEP < 1 )) && STEP=1

