        sampled=$(awk -v s="${ROW_CELLS_RAW[$r]}" -v d=$'\x01' -v step="$STEP" 'BEGIN{
            n=split(s,a,d)
            out=""
            for (i=1; i<=n; i+=step) {
                if (out=="") out=a[i]
                else out=out d a[i]
            }
            print out
        }')
        SCALED_ROW_CELLS[$scaled_h]="$sampled"
        SCALED_ROW_WIDTH[$scaled_h]=$(awk -v s="$sampled" -v d=$'\x01' 'BEGIN{n=split(s,a,d); print n}')
        scaled_h=$(( scaled_h + 1 ))
    done
    # Replace originals
    ROW_CELLS_RAW=( "${SCALED_ROW_CELLS[@]}" )
    ROW_WIDTH=( "${SCALED_ROW_WIDTH[@]}" )
    HEIGHT=$scaled_h
    CANVAS_W=${ROW_WIDTH[0]:-0}
    for (( r=1; r<HEIGHT; r++ )); do
        (( ROW_WIDTH[r] > CANVAS_W )) && CANVAS_W=${ROW_WIDTH[r]}
    done
else
    HEIGHT=$RAW_HEIGHT
    CANVAS_W=$RAW_WIDTH
fi

# --- Image placement: center the (possibly scaled) image inside the terminal ---
IMG_ROW_OFF=$(( (TERM_ROWS - HEIGHT) / 2 ))
(( IMG_ROW_OFF < 0 )) && IMG_ROW_OFF=0
IMG_COL_OFF=$(( (TERM_COLS - CANVAS_W) / 2 ))
(( IMG_COL_OFF < 0 )) && IMG_COL_OFF=0

# Lyrics are centered on the full terminal width, not the image width
LYRIC_CANVAS_W=$TERM_COLS

# --- Render each chorus line in every font band ---
# For chorus line L rendered in band B we store:
#   RENDERED[L,B,r]   : padded text row r
#   RH[L,B]           : block height in rows
#   RW[L,B]           : block width in characters
declare -A RENDERED
declare -A RH
declare -A RW

NUM_LINES=${#CHORUS[@]}

render_phrase_in_font() {
    # Args: line_idx, band_idx, font, width, text
    local L=$1 B=$2 font=$3 tw=$4 text=$5
    local -a raw_rows
    mapfile -t raw_rows < <( LANG=en_US.UTF-8 toilet -f "$font" -w "$tw" "$text" )

    # Trim leading/trailing all-blank rows
    local first=0
    local last=$(( ${#raw_rows[@]} - 1 ))
    local line line_trim
    while (( first <= last )); do
        line="${raw_rows[$first]}"
        line_trim="${line//[[:space:]]/}"
        [[ -n "$line_trim" ]] && break
        first=$(( first + 1 ))
    done
    while (( last >= first )); do
        line="${raw_rows[$last]}"
        line_trim="${line//[[:space:]]/}"
        [[ -n "$line_trim" ]] && break
        last=$(( last - 1 ))
    done
    local block_h=$(( last - first + 1 ))
    (( block_h < 1 )) && block_h=1

    # Trim trailing spaces per row, find max visible width
    local max_w=0 br raw info w trimmed
    for (( br=0; br<block_h; br++ )); do
        raw="${raw_rows[$((first + br))]:-}"
        info=$(LANG=en_US.UTF-8 awk -v line="$raw" 'BEGIN{
            sub(/ +$/, "", line)
            print length(line) "\t" line
        }')
        w="${info%%$'\t'*}"
        trimmed="${info#*$'\t'}"
        (( w > max_w )) && max_w=$w
        RENDERED[$L,$B,$br]="$trimmed"
    done

    # Pad rows to max_w characters
    local cur cur_w pad_n pad
    for (( br=0; br<block_h; br++ )); do
        cur="${RENDERED[$L,$B,$br]}"
        cur_w=$(LANG=en_US.UTF-8 awk -v line="$cur" 'BEGIN{print length(line)}')
        if (( cur_w < max_w )); then
            pad_n=$(( max_w - cur_w ))
            pad=$(printf '%*s' "$pad_n" '')
            RENDERED[$L,$B,$br]="${cur}${pad}"
        fi
    done

    RH[$L,$B]=$block_h
    RW[$L,$B]=$max_w
}

echo "Pre-rendering chorus in $NUM_BANDS fonts..." >&2
for (( L=0; L<NUM_LINES; L++ )); do
    for (( B=0; B<NUM_BANDS; B++ )); do
        IFS='|' read -r _bname _bfont <<<"${BANDS[$B]}"
        render_phrase_in_font "$L" "$B" "$_bfont" "$TOILET_WIDTH" "${CHORUS[$L]}"
    done
done

# --- Helpers ---

# Redraw a contiguous range of image cells corresponding to terminal cells.
# Args: term_row, term_col, length-in-chars
# Maps terminal coords back to image coords using IMG_ROW_OFF/IMG_COL_OFF.
# If the requested range falls outside the image bounds, blanks those cells.
redraw_cells() {
    local trow=$1 tcol=$2 len=$3
    (( trow < 0 || trow >= TERM_ROWS )) && return
    (( len <= 0 )) && return

    local irow=$(( trow - IMG_ROW_OFF ))
    local icol_start=$(( tcol - IMG_COL_OFF ))
    local icol_end=$(( icol_start + len - 1 ))

    tput cup "$trow" "$tcol"

    # If row is outside the image entirely, just blank the range
    if (( irow < 0 || irow >= HEIGHT )); then
        printf '%*s' "$len" ''
        return
    fi

    local row_w=${ROW_WIDTH[$irow]}
    local IFS=$'\x01'
    local -a cells
    # shellcheck disable=SC2206
    cells=( ${ROW_CELLS_RAW[$irow]} )
    unset IFS

    local out="" j
    for (( j=icol_start; j<=icol_end; j++ )); do
        if (( j < 0 || j >= row_w )); then
            out+=' '
        else
            out+="${cells[$j]}"
        fi
    done
    printf '%s' "$out"
}

# Draw one row of a phrase block.
# Args: term_row, term_col, color_escape, text
draw_phrase_row() {
    local row=$1 col=$2 color=$3 text=$4
    (( row < 0 || row >= TERM_ROWS )) && return
    tput cup "$row" "$col"
    printf '%s%s%s' "$color" "$text" "$RESET"
}

# Pick band index from the bottom_y of a line (0 = top band/smallest, NUM_BANDS-1 = bottom/biggest).
# Args: bottom_y_int (terminal row)
pick_band() {
    local by=$1
    # Map bottom_y in [0..CRAWL_ROWS-1] -> band in [0..NUM_BANDS-1].
    # by near CRAWL_ROWS-1 = bottom of screen = biggest band (last).
    # by near 0 = top of screen = smallest band (first).
    if (( by >= CRAWL_ROWS - 1 )); then
        echo $(( NUM_BANDS - 1 ))
        return
    fi
    if (( by <= 0 )); then
        echo 0
        return
    fi
    local b=$(( by * NUM_BANDS / CRAWL_ROWS ))
    (( b < 0 )) && b=0
    (( b >= NUM_BANDS )) && b=$(( NUM_BANDS - 1 ))
    echo "$b"
}

# Compute 24-bit color escape for a given bottom_y.
# Linearly interpolates between COLOR_TOP (when by=0) and COLOR_BOT (when by=CRAWL_ROWS-1).
# Args: bottom_y_int
color_for_y() {
    local by=$1
    local span=$(( CRAWL_ROWS - 1 ))
    (( span < 1 )) && span=1
    (( by < 0 )) && by=0
    (( by > span )) && by=$span
    local t_num=$by
    local t_den=$span
    local r=$(( COLOR_TOP_R + (COLOR_BOT_R - COLOR_TOP_R) * t_num / t_den ))
    local g=$(( COLOR_TOP_G + (COLOR_BOT_G - COLOR_TOP_G) * t_num / t_den ))
    local b=$(( COLOR_TOP_B + (COLOR_BOT_B - COLOR_TOP_B) * t_num / t_den ))
    printf '\e[1;38;2;%d;%d;%dm' "$r" "$g" "$b"
}

# --- Cleanup ---
cleanup() {
    tput sgr0
    tput cnorm
    # Park cursor at the last terminal row so subsequent shell output starts cleanly.
    tput cup $(( TERM_ROWS - 1 )) 0
    echo
    exit 0
}
trap cleanup INT

# --- Main ---
main() {
    clear
    tput civis

    # 1. Draw the image once
    tput cup 0 0
    local line
    for line in "${IMAGE[@]}"; do
        printf '%s\n' "$line"
    done

    sleep 1

    # 2. Crawl loop.
    # Each chorus line L has a floating bottom_y that decreases over time
    # (line drifts upward). When bottom_y crosses band boundaries, the line is
    # re-rendered in a different font.
    #
    # State per line:
    #   LINE_BOTTOM[L]   : current bottom_y (integer; we step by 1 per frame)
    #   LINE_ACTIVE[L]   : 0 = not spawned yet, 1 = on screen, 2 = finished
    #   LAST_R0/R1/C0/C1[L] : last drawn bounding box (for restoration)

    declare -a LINE_BOTTOM LINE_ACTIVE LAST_R0 LAST_R1 LAST_C0 LAST_C1
    local L
    for (( L=0; L<NUM_LINES; L++ )); do
        # Spawn each line at the bottom of the terminal so the crawl covers
        # the full screen height (not just the image region).
        LINE_BOTTOM[L]=$(( TERM_ROWS - 1 ))
        LINE_ACTIVE[L]=0
        LAST_R0[L]=-1
    done
    LINE_ACTIVE[0]=1   # spawn first line immediately

    local frame=0
    local next_spawn=1
    local done_count=0

    while (( done_count < NUM_LINES )); do
        # Spawn next line on cadence
        if (( next_spawn < NUM_LINES )); then
            if (( frame >= next_spawn * LINE_STAGGER_FRAMES )); then
                LINE_ACTIVE[$next_spawn]=1
                next_spawn=$(( next_spawn + 1 ))
            fi
        fi

        local rr cc
        for (( L=0; L<NUM_LINES; L++ )); do
            (( LINE_ACTIVE[L] != 1 )) && continue

            local by=${LINE_BOTTOM[$L]}
            local B
            B=$(pick_band "$by")
            local bh=${RH[$L,$B]}
            local bw=${RW[$L,$B]}
            local top=$(( by - bh + 1 ))
            # Center horizontally across the full terminal width, not just the image.
            local col=$(( (LYRIC_CANVAS_W - bw) / 2 ))
            (( col < 0 )) && col=0

            # Restore previous bounding box if any
            if (( LAST_R0[L] >= 0 )); then
                local pr0=${LAST_R0[$L]} pr1=${LAST_R1[$L]}
                local pc0=${LAST_C0[$L]} pc1=${LAST_C1[$L]}
                local plen=$(( pc1 - pc0 + 1 ))
                for (( rr=pr0; rr<=pr1; rr++ )); do
                    redraw_cells "$rr" "$pc0" "$plen"
                done
            fi

            # If the line has fully scrolled off the top, mark done
            if (( by < 0 )); then
                LINE_ACTIVE[$L]=2
                LAST_R0[$L]=-1
                done_count=$(( done_count + 1 ))
                continue
            fi

            # Draw at new position with band-appropriate color
            local color
            color=$(color_for_y "$by")
            local br
            for (( br=0; br<bh; br++ )); do
                local r=$(( top + br ))
                (( r < 0 || r >= TERM_ROWS )) && continue
                draw_phrase_row "$r" "$col" "$color" "${RENDERED[$L,$B,$br]}"
            done

            # Record new bounding box (clipped to screen)
            local r0=$top
            local r1=$(( top + bh - 1 ))
            (( r0 < 0 )) && r0=0
            (( r1 >= TERM_ROWS )) && r1=$(( TERM_ROWS - 1 ))
            LAST_R0[$L]=$r0
            LAST_R1[$L]=$r1
            LAST_C0[$L]=$col
            LAST_C1[$L]=$(( col + bw - 1 ))

            # Advance: move up by 1 row per frame
            LINE_BOTTOM[$L]=$(( by - 1 ))
        done

        sleep "$SCROLL_DELAY"
        frame=$(( frame + 1 ))
    done

    # Final cleanup: restore any still-covered cells
    for (( L=0; L<NUM_LINES; L++ )); do
        if (( LAST_R0[L] >= 0 )); then
            local pr0=${LAST_R0[$L]} pr1=${LAST_R1[$L]}
            local pc0=${LAST_C0[$L]} pc1=${LAST_C1[$L]}
            local plen=$(( pc1 - pc0 + 1 ))
            for (( rr=pr0; rr<=pr1; rr++ )); do
                redraw_cells "$rr" "$pc0" "$plen"
            done
        fi
    done

    cleanup
}

main
